from openpyxl import load_workbook
from openpyxl.utils import get_column_letter
path='/root/output/result.xlsx'
wb=load_workbook(path, data_only=False)
ws=wb['Task']
blocks=[('H12:L17',12,17),('H19:L24',19,24),('H26:L31',26,31),('H35:L40',35,40),('H42:L47',42,47),('H50:L50',50,50)]
errors=[]
print('Verification cell values:')
for name, r1, r2 in blocks:
    print('\n' + name)
    for r in range(r1, r2+1):
        vals=[]
        for c in range(8,13):
            cell=ws.cell(r,c)
            v=cell.value
            vals.append(f'{cell.coordinate}={v!r}')
            if v is None:
                errors.append(f'{cell.coordinate} is None')
            elif not (isinstance(v,str) and v.startswith('=')):
                errors.append(f'{cell.coordinate} is not a formula string: {v!r}')
        print(' | '.join(vals))

# Detailed contract checks
for r in list(range(12,18))+list(range(19,25))+list(range(26,32)):
    for c in range(8,13):
        col=get_column_letter(c)
        expected=f'=INDEX(Data!$H$21:$L$38,MATCH($D{r},Data!$D$21:$D$38,0),MATCH({col}$10,Data!$H$4:$L$4,0))'
        actual=ws.cell(r,c).value
        if actual != expected:
            errors.append(f'{ws.cell(r,c).coordinate} INDEX/MATCH mismatch: {actual!r} expected {expected!r}')

for c in range(8,13):
    col=get_column_letter(c)
    if ws.cell(46,c).value != f'=PERCENTILE({col}35:{col}40,0.25)':
        errors.append(f'{col}46 percentile mismatch: {ws.cell(46,c).value!r}')
    if ws.cell(47,c).value != f'=PERCENTILE({col}35:{col}40,0.75)':
        errors.append(f'{col}47 percentile mismatch: {ws.cell(47,c).value!r}')
    for r in range(42,48):
        v=ws.cell(r,c).value or ''
        if 'PERCENTILE.INC' in v:
            errors.append(f'{ws.cell(r,c).coordinate} uses PERCENTILE.INC')
    expected_sumprod=f'=SUMPRODUCT({col}35:{col}40,{col}26:{col}31)/SUM({col}26:{col}31)'
    if ws.cell(50,c).value != expected_sumprod:
        errors.append(f'{col}50 SUMPRODUCT mismatch: {ws.cell(50,c).value!r}')

print('\nVerification summary:')
if errors:
    print('FAILED')
    for e in errors:
        print('ERROR:', e)
    raise SystemExit(1)
else:
    print('PASSED: no None cells; all checked cells are formulas; PERCENTILE legacy function used; INDEX/MATCH ranges correct; SUMPRODUCT formulas are in row 50.')
